  77 }
  78 
  79 const ReportResults = ({ activePanelKey }: ReportResultsProps) => {
  80   const { t } = useLocalization();
  81   const project = useBuilderStore(state => state.project);
  82   const version = useBuilderStore(state => state.version);
  83   const updateProjectFromMarkdown = useBuilderStore(state => state.updateProjectFromMarkdown);
  84   const selectedFileId = useBuilderStore(state => state.selectedFileId);
  85   const [isSuggestionVisible, setIsSuggestionVisible] = useState(true);
