  88     updateProjectFromMarkdown(newMarkdown);
  89   };
  90   
  91   const hasContent = project?.content && project.content.length > 0;
  92 
  93   // Logic for suggestions
  94   const getSuggestion = () => {
  95     if (!project || !project.sections) return "Start by adding a chapter or applying a template.";
  96     const emptySection = project.sections.find(s => !s.content);
  97     if (emptySection) {
  98         return `Suggestion: Try generating the "${emptySection.title}" section next.`;
  99     }
 100     return "All sections have content. You can now review or export your document.";
 101   };
 102   const suggestion = getSuggestion();
 103 
