 129             return (
 130                 <A4Page>
 131                     <FileContentViewer fileName={selectedFile.fileName} content={selectedFile.content} />
 132                 </A4Page>
 133             );
 134         }
 135         case 'generate':
 136         default:
 137              if (hasContent) {
 138                  return (
 139                     <A4Page>
 140                         <MarkdownEditor
 141                             key={version} // Re-mount editor when version changes
 142                             content={project?.fullMarkdownContent || ''}
 143                             onChange={handleContentChange}
 144                         />
 145                     </A4Page>
 146                  )
 147              }
 148              return (
 149                 <div className="max-w-[210mm] mx-auto my-4">
 150                     <ReportSteps />
 151                 </div>
 152              )
 153     }
 154   }
 155 
 156   return (
 157     <div className="h-full flex flex-col overflow-hidden rounded-lg border bg-card text-card-foreground shadow-sm">
 158       <Collapsible open={isSuggestionVisible} onOpenChange={setIsSuggestionVisible} className="border-b border-border/60">
 159         <CollapsibleTrigger asChild>
 160             <div className="flex items-center justify-between p-5 cursor-pointer bg-muted/30 hover:bg-muted/40">
 161                 <div>
 162                     <CardTitle className="font-headline text-base font-semibold tracking-tight">
 163                       {t('builder.reportGenerator.resultsTitle')}
 164                     </CardTitle>
 165                     <CardDescription className="text-xs">
 166                       {t('builder.reportGenerator.resultsDesc')}
 167                     </CardDescription>
 168                 </div>
 169                 <Button variant="ghost" size="sm" className="shrink-0">
 170                     <ChevronDown className={`h-4 w-4 transition-transform ${isSuggestionVisible ? '' : '-rotate-90'}`} />
 171                     <span className="sr-only">Toggle suggestions</span>
 172                 </Button>
 173             </div>
 174         </CollapsibleTrigger>
 175         <CollapsibleContent>
 176             <div className="p-5 border-t border-border/60 bg-muted/20 space-y-2">
 177                 <div className="flex items-center gap-2 text-sm">
 178                     <Lightbulb className="h-4 w-4 text-yellow-500" />
 179                     <span className="font-semibold">Suggestion:</span>
 180                     <span className="text-muted-foreground">{suggestion}</span>
 181                 </div>
 182                 {project?.meta.updated && (
 183                     <div className="flex items-center gap-2 text-sm">
 184                         <History className="h-4 w-4 text-blue-500" />
 185                         <span className="font-semibold">Last operation:</span>
 186                         <span className="text-muted-foreground">
 187                             Project updated {formatDistanceToNow(new Date(project.meta.updated), { addSuffix: true })}
 188                         </span>
 189                     </div>
 190                 )}
 191             </div>
 192         </CollapsibleContent>
 193       </Collapsible>
 194 
 195       <CardContent className="flex-grow flex flex-col p-0 bg-slate-200 dark:bg-slate-900/50 min-h-0">
 196           <ScrollArea className="flex-grow">
 197               <div className="py-5">
 198                   {renderContent()}
 199               </div>
 200           </ScrollArea>
 201       </CardContent>
 202     </div>
 203   );
 204 };
 205 
 206 export default React.memo(ReportResults);
 207 
